{
  "doc_type": "Notice officielle",
  "audience": "Personnes à revenu modeste résidant à Exempleville et souhaitant une réduction de leurs primes d'assurance maladie",
  "core": {
    "what": {
      "text": "Réduction individuelle des primes d'assurance maladie pour 2027.",
      "segment_ids": ["s0001"]
    },
    "must_do": {
      "text": "Remplir le formulaire de demande, le signer, joindre les pièces requises et le déposer avant le 31 mars 2027.",
      "segment_ids": ["s0007", "s0009"]
    },
    "deadline": {
      "text": "Déposer la demande au plus tard le 31 mars 2027 ; annoncer toute modification dans les 30 jours ; réclamer la décision dans les 30 jours.",
      "segment_ids": ["s0007", "s0012", "s0014"]
    },
    "cost": {
      "text": null,
      "segment_ids": []
    },
    "contact": {
      "text": "Agence d'assurances sociales d'Exempleville, téléphone 022 123 45 67, e‑mail rip@exempleville.example, site www.exempleville.example/rip.",
      "segment_ids": ["s0016", "s0017"]
    }
  },
  "facts": [
    {
      "id": "f01",
      "kind": "deadline",
      "text": "La demande doit être déposée au plus tard le 31 mars 2027.",
      "value_norm": "2027-03-31",
      "segment_ids": ["s0007"],
      "must_keep": true
    },
    {
      "id": "f02",
      "kind": "condition",
      "text": "Revenu déterminant ≤ 42 000 CHF pour une personne seule.",
      "value_norm": "42000",
      "segment_ids": ["s0005"],
      "must_keep": true
    },
    {
      "id": "f03",
      "kind": "condition",
      "text": "Revenu déterminant ≤ 61 000 CHF pour une personne mariée.",
      "value_norm": "61000",
      "segment_ids": ["s0005"],
      "must_keep": true
    },
    {
      "id": "f04",
      "kind": "condition",
      "text": "La limite de revenu augmente de 9 000 CHF pour chaque enfant à charge.",
      "value_norm": "9000",
      "segment_ids": ["s0006"],
      "must_keep": true
    },
    {
      "id": "f05",
      "kind": "obligation",
      "text": "Le formulaire de demande doit être dûment rempli et signé.",
      "value_norm": null,
      "segment_ids": ["s0007"],
      "must_keep": true
    },
    {
      "id": "f06",
      "kind": "obligation",
      "text": "Joindre une copie de la dernière décision de taxation et de la police d'assurance‑maladie.",
      "value_norm": null,
      "segment_ids": ["s0009"],
      "must_keep": true
    },
    {
      "id": "f07",
      "kind": "obligation",
      "text": "Toute modification de situation doit être annoncée par écrit dans les 30 jours.",
      "value_norm": null,
      "segment_ids": ["s0012"],
      "must_keep": true
    },
    {
      "id": "f08",
      "kind": "right",
      "text": "La réduction des primes est versée directement à l'assureur‑maladie.",
      "value_norm": null,
      "segment_ids": ["s0010"],
      "must_keep": true
    },
    {
      "id": "f09",
      "kind": "obligation",
      "text": "Une réclamation écrite doit être faite dans les 30 jours suivant la notification de la décision.",
      "value_norm": null,
      "segment_ids": ["s0014"],
      "must_keep": true
    },
    {
      "id": "f10",
      "kind": "contact",
      "text": "Agence d'assurances sociales d'Exempleville, téléphone 0221234567, e‑mail rip@exempleville.example.",
      "value_norm": "0221234567",
      "segment_ids": ["s0016"],
      "must_keep": true
    },
    {
      "id": "f11",
      "kind": "contact",
      "text": "Informations complémentaires sur www.exempleville.example/rip.",
      "value_norm": "www.exempleville.example/rip",
      "segment_ids": ["s0017"],
      "must_keep": true
    }
  ],
  "hard_terms": [
    {
      "term": "revenu déterminant",
      "explanation": "Le revenu imposable qui sert de base pour calculer la réduction. Il provient de la décision de taxation officielle.",
      "segment_ids": ["s0004"]
    },
    {
      "term": "police d'assurance‑maladie",
      "explanation": "Le contrat qui lie l'assuré à son assureur pour les soins de santé. Il indique le montant des primes à payer.",
      "segment_ids": ["s0009"]
    },
    {
      "term": "agence d'assurances sociales",
      "explanation": "L'office cantonal qui gère les assurances sociales, dont l'assurance maladie. C’est l’organisme à qui il faut envoyer la demande.",
      "segment_ids": ["s0007", "s0016"]
    },
    {
      "term": "réduction des primes",
      "explanation": "Une baisse du montant à payer pour l'assurance maladie obligatoire. Elle est accordée aux personnes à revenu modeste.",
      "segment_ids": ["s0003"]
    },
    {
      "term": "déclaration de taxation",
      "explanation": "Le document officiel qui indique le revenu imposable d’une personne. Il doit être joint à la demande de réduction.",
      "segment_ids": ["s0009"]
    }
  ],
  "omit_candidates": [
    {
      "segment_ids": ["s0011"],
      "reason": "Information sur le versement en espèces, peu pertinente pour la demande."
    },
    {
      "segment_ids": ["s0013"],
      "reason": "Mention de restitution des prestations indûment perçues, redondante avec la réclamation."
    },
    {
      "segment_ids": ["s0015"],
      "reason": "Exigence de motivation de la réclamation, déjà implicite dans la procédure."
    }
  ]
}

{
  "repairs": [
    {
      "id": "b004",
      "texts": [
        "Vous avez le droit.",
        "Vous habitez à Exempleville depuis le 1er janvier 2027."
      ]
    },
    {
      "id": "b005",
      "texts": [
        "Le revenu déterminant ne doit pas dépasser 42 000 francs.",
        "Vous êtes seul."
      ]
    },
    {
      "id": "b006",
      "texts": [
        "Le revenu déterminant ne doit pas dépasser 61 000 francs.",
        "Vous êtes marié."
      ]
    },
    {
      "id": "b007",
      "texts": [
        "Le montant maximum augmente de 9 000 francs pour chaque enfant à charge."
      ]
    },
    {
      "id": "b016",
      "texts": [
        "Comment la réduction est‑elle payée ?"
      ]
    },
    {
      "id": "b017",
      "texts": [
        "L’agence d’assurances sociales paie la réduction directement à votre assureur‑maladie."
      ]
    }
  ],
  "additions": []
}
